import React, { useState } from "react";
import "./ClientsList.css";

const Clients = [ //lista temporal de clientes, cambiar a futuro con datos reales
  { id: 1, title: "Cliente 1",
    invoices: [
      { id: 1, date: "2024-01-10" },
      { id: 2, date: "2024-02-15" },
    ], },
  
  { id: 2, title: "Cliente 2",
    invoices: [
      { id: 3, date: "2024-03-01" },
      { id: 4, date: "2024-04-20" },
    ], },
  { id: 3, title: "Cliente 3",
    invoices: [], },
];

const ClientsList = () => {
  const [query, setQuery] = useState("");
  const [clientFilters, setClientFilters] = useState({});
  const [activeClient, setActiveClient] = useState(null);

  const filteredClients = Clients.filter((c) =>
    c.title.toLowerCase().includes(query.toLowerCase())
  );

  const applyClientFilters = (client) => {
    const filters = clientFilters[client.id];
    let results = [...(client.invoices || [])];

    if (!filters) return results;
    if (filters.dateFrom && filters.dateTo) {
      results = results.filter((inv) => {
        const date = new Date(inv.date);
        return (
          date >= new Date(filters.dateFrom) &&
          date <= new Date(filters.dateTo)
        );
      });
    }
    return results;
  };

  const handleFilterChange = (clientId, field, value) => {
    setClientFilters({
      ...clientFilters,
      [clientId]: {
        ...clientFilters[clientId],
        [field]: value,
      },
    });
  };

  return (
    <div>
      <h2>Clientes</h2>

      <input
        type="text"
        placeholder="Buscar cliente..."
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />

      {filteredClients.length === 0 ? (
        <p>No existen facturas a este</p>
      ) : (
        filteredClients.map((client) => {
          const filteredInvoices = applyClientFilters(client);

          return (
            <div key={client.id} style={{ marginBottom: "20px" }}>
              <h3>{client.title}</h3>

              <button
                onClick={() =>
                  setActiveClient(
                    activeClient === client.id ? null : client.id
                  )
                }
              >
                Filtro
              </button>

              {activeClient === client.id && (
                <div>
                  <p>Rango de fechas:</p>

                  <input
                    type="date"
                    onChange={(e) =>
                      handleFilterChange(
                        client.id,
                        "dateFrom",
                        e.target.value
                      )
                    }
                  />

                  <input
                    type="date"
                    onChange={(e) =>
                      handleFilterChange(
                        client.id,
                        "dateTo",
                        e.target.value
                      )
                    }
                  />
                </div>
              )}

              {/* Mostrar facturas */}
              <ul>
                {filteredInvoices.length === 0 ? (
                  <p>No hay facturas para este filtro</p>
                ) : (
                  filteredInvoices.map((inv) => (
                    <li key={inv.id}>
                      Factura #{inv.id} - {inv.date}
                    </li>
                  ))
                )}
              </ul>
            </div>
          );
        })
      )}
    </div>
  );
};

export default ClientsList;
